/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  let output = '';
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Launch timed out')), 10000);
    child.once('error', reject);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = /listening on port (\\d+)/.exec(output);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health failed');
  console.log('npm start launch and health check passed');
} finally {
  const stopped = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await stopped;
  await rm(directory, { recursive: true, force: true });
}
JS
"

